package yagen.waitmydawn.kb.ui;

import javafx.application.Platform;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.scene.image.*;
import javafx.geometry.Insets;
import java.util.*;
import java.util.concurrent.Executor;
import java.nio.file.*;
import yagen.waitmydawn.kb.service.*;
import yagen.waitmydawn.kb.model.*;
import yagen.waitmydawn.kb.config.AppConfig;

/** 快照分页目录只读取本地数据库，显式操作才生成派生图片。 */
public final class RuntimeBrowser extends VBox {
    private static final Executor DIRECTORY_WORKER=java.util.concurrent.Executors.newFixedThreadPool(2,r->{var thread=new Thread(r,"mkb-catalog");thread.setDaemon(true);return thread;});
    private final RuntimeCatalog catalog;private final DatabaseBuilder db;private final AppConfig config;private final Executor worker;private final RuntimeCatalog.Kind kind;
    private final ComboBox<RuntimeCatalog.Profile> profiles=new ComboBox<>();private final TextField search=new TextField(),namespace=new TextField();
    private final ListView<RuntimeCatalog.Entry> list=new ListView<>();private final TextArea json=new TextArea();private final Label status=new Label(),origin=new Label();private final ImageView image=new ImageView();private final Button render=new Button("渲染 / 查看缓存");private final CheckBox allLayers=new CheckBox("分层总览（最多8层）");private final Spinner<Integer> layoutLayer=new Spinner<>(-4096,4096,0);private int offset,total;private volatile long request,selection,profileRequest;private boolean refreshingProfiles;
    public RuntimeBrowser(DatabaseBuilder db,AppConfig config,Executor worker,RuntimeCatalog.Kind kind,String title) {
        super(10);this.db=db;this.config=config;this.worker=DIRECTORY_WORKER;this.kind=kind;catalog=new RuntimeCatalog(db);setPadding(new Insets(20));getStyleClass().add("workspace-page");list.setId("runtime-entry-list");json.setId("runtime-json");render.setId("runtime-render");
        var heading=new Label(title);heading.getStyleClass().add("page-title");profiles.setId("runtime-profile");status.setId("runtime-status");profiles.setPrefWidth(300);profiles.setMaxWidth(380);namespace.setPrefWidth(170);search.setPromptText(kind==RuntimeCatalog.Kind.ITEMS||kind==RuntimeCatalog.Kind.ENTITIES?"搜索注册名（不搜索JSON内容）":"搜索名称、翻译或数据内容");namespace.setPromptText(kind==RuntimeCatalog.Kind.LANGUAGE?"翻译键前缀（可选）":"命名空间（可选）");
        var refresh=new Button("刷新");var tools=new HBox(8,profiles,search,namespace,refresh);HBox.setHgrow(search,Priority.ALWAYS);HBox.setHgrow(profiles,Priority.ALWAYS);
        var prev=new Button("上一页");var next=new Button("下一页");var pages=new HBox(10,prev,next,status);prev.setOnAction(e->{if(offset>0){offset=Math.max(0,offset-50);load();}});next.setOnAction(e->{if(offset+50<total){offset+=50;load();}});
        json.setEditable(false);json.setWrapText(false);json.setStyle("-fx-font-family: 'Consolas';");json.setPromptText("选中条目查看格式化JSON");origin.setWrapText(true);image.setPreserveRatio(true);image.setFitWidth(600);image.setFitHeight(400);image.setSmooth(false);
        image.setOnMouseClicked(e->{if(e.getClickCount()==2)zoom();});var picture=new StackPane(image);var scroll=new ScrollPane(picture);scroll.setFitToWidth(true);if(kind==RuntimeCatalog.Kind.TEMPLATES||kind==RuntimeCatalog.Kind.MULTIBLOCKS||kind==RuntimeCatalog.Kind.RECIPES||kind==RuntimeCatalog.Kind.LOOT||kind==RuntimeCatalog.Kind.TRADES||kind==RuntimeCatalog.Kind.BREWING||kind==RuntimeCatalog.Kind.WORKSTATIONS){image.setFitHeight(0);scroll.viewportBoundsProperty().addListener((o,a,b)->{if(b.getWidth()>0)image.setFitWidth(Math.max(160,b.getWidth()-20));});}var inspect=new Button("查看快照来源与完整描述");inspect.setOnAction(e->{var p=profiles.getValue();if(p!=null)try{json.setText(new com.fasterxml.jackson.databind.ObjectMapper().readTree(p.descriptor()).toPrettyString());}catch(Exception ex){status.setText(ex.getMessage());}});
        var expand=new Button("放大查看");expand.setOnAction(e->zoom());
        var export=new Button("导出完整JSON…");export.setOnAction(e->{var entry=list.getSelectionModel().getSelectedItem();if(entry==null)return;var chooser=new javafx.stage.FileChooser();chooser.setInitialFileName(entry.key().replaceAll("[^a-zA-Z0-9._-]","_")+".json");var file=chooser.showSaveDialog(getScene().getWindow());if(file!=null)worker.execute(()->{try{Files.writeString(file.toPath(),catalog.pretty(entry));}catch(Exception ex){Platform.runLater(()->status.setText(ex.getMessage()));}});});
        var related=new Button("关联规则 / 掉落表…");related.setOnAction(e->related());render.setDisable(true);render.setOnAction(e->render());allLayers.setSelected(true);layoutLayer.setEditable(true);layoutLayer.disableProperty().bind(allLayers.selectedProperty());var layerTools=new HBox(8,allLayers,new Label("单层Y："),layoutLayer);layerTools.setVisible(kind==RuntimeCatalog.Kind.TEMPLATES||kind==RuntimeCatalog.Kind.MULTIBLOCKS);layerTools.setManaged(layerTools.isVisible());var right=new VBox(8,origin,layerTools,new HBox(8,render,expand,inspect,export,related),new WorkspaceLayout().vertical("runtime-preview-"+kind,scroll,json,.45,90,120));VBox.setVgrow(right.getChildren().getLast(),Priority.ALWAYS);
        var split=new WorkspaceLayout().horizontal("runtime-catalog-"+kind,list,right,.38,200,330);VBox.setVgrow(split,Priority.ALWAYS);getChildren().addAll(heading,tools,pages,split);
        list.getSelectionModel().selectedItemProperty().addListener((o,a,b)->show(b));profiles.valueProperty().addListener((o,a,b)->{if(!refreshingProfiles){offset=0;load();}});var delay=new javafx.animation.PauseTransition(javafx.util.Duration.millis(250));delay.setOnFinished(e->{offset=0;load();});search.textProperty().addListener((o,a,b)->delay.playFromStart());namespace.textProperty().addListener((o,a,b)->delay.playFromStart());refresh.setOnAction(e->refresh());
        refresh();
    }
    public void refresh(){
        long token=++profileRequest;request++;selection++;catalog.invalidate();offset=0;total=0;
        String previous=profiles.getValue()==null?null:profiles.getValue().id();
        list.getItems().clear();json.clear();origin.setText("");image.setImage(null);render.setDisable(true);profiles.setDisable(true);status.setText("重新加载快照与目录…");
        worker.execute(()->{if(token!=profileRequest)return;try{
            var values=catalog.profiles();String active=RuntimeKnowledgeStore.active(db);
            Platform.runLater(()->{if(token!=profileRequest)return;refreshingProfiles=true;
                try{profiles.getItems().setAll(values);profiles.getSelectionModel().select(values.stream().filter(p->p.id().equals(previous)).findFirst().orElseGet(()->values.stream().filter(p->p.id().equals(active)).findFirst().orElse(values.isEmpty()?null:values.getFirst())));}
                finally{refreshingProfiles=false;profiles.setDisable(false);}
                if(profiles.getValue()==null)status.setText("当前数据库没有MKB-Export完整快照");else load();
            });
        }catch(Exception failure){Platform.runLater(()->{if(token==profileRequest){profiles.setDisable(false);status.setText("目录初始化失败："+failure.getMessage());}});}});
    }
    private Image preview(byte[] bytes){
        try{var source=javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(bytes));if(source!=null&&kind==RuntimeCatalog.Kind.ITEMS){int factor=Math.max(1,Math.min(320/source.getWidth(),320/source.getHeight()));var scaled=new java.awt.image.BufferedImage(source.getWidth()*factor,source.getHeight()*factor,2);var g=scaled.createGraphics();try{g.setRenderingHint(java.awt.RenderingHints.KEY_INTERPOLATION,java.awt.RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);g.drawImage(source,0,0,scaled.getWidth(),scaled.getHeight(),null);}finally{g.dispose();}var out=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(scaled,"png",out);image.setFitWidth(scaled.getWidth());image.setFitHeight(scaled.getHeight());return new Image(new java.io.ByteArrayInputStream(out.toByteArray()));}}catch(java.io.IOException ignored){}return new Image(new java.io.ByteArrayInputStream(bytes));
    }
    private void zoom(){if(image.getImage()==null)return;var dialog=new Dialog<Void>();dialog.setTitle("本地图片预览");dialog.setResizable(true);dialog.getDialogPane().getButtonTypes().add(ButtonType.CLOSE);dialog.getDialogPane().setPrefSize(1000,760);if(getScene()!=null)dialog.initOwner(getScene().getWindow());var view=new ImageView(image.getImage());view.setPreserveRatio(true);view.setSmooth(false);var scale=new Slider(.1,3,1);view.setFitWidth(image.getImage().getWidth());scale.valueProperty().addListener((o,a,b)->view.setFitWidth(image.getImage().getWidth()*b.doubleValue()));var scroll=new ScrollPane(view);scroll.setPannable(true);var body=new VBox(10,new Label("缩放；实体图独立取景，不能据此比较实际体型"),scale,scroll);VBox.setVgrow(scroll,Priority.ALWAYS);dialog.getDialogPane().setContent(body);dialog.show();}
    private void load(){var profile=profiles.getValue();if(profile==null)return;long token=++request;String query=search.getText(),ns=namespace.getText();int start=offset;selection++;image.setImage(null);render.setDisable(true);status.setText("读取本地目录…");worker.execute(()->{if(token!=request)return;try{if(kind==RuntimeCatalog.Kind.STRUCTURES||kind==RuntimeCatalog.Kind.TEMPLATES||kind==RuntimeCatalog.Kind.MULTIBLOCKS||kind==RuntimeCatalog.Kind.SPAWNS||kind==RuntimeCatalog.Kind.POTIONS||kind==RuntimeCatalog.Kind.EFFECTS||kind==RuntimeCatalog.Kind.ENCHANTMENTS||kind==RuntimeCatalog.Kind.LOOT_SOURCES||kind==RuntimeCatalog.Kind.TRADES||kind==RuntimeCatalog.Kind.BREWING||kind==RuntimeCatalog.Kind.WORKSTATIONS){String capability=switch(kind){case STRUCTURES->"structures";case TEMPLATES->"structure_templates";case MULTIBLOCKS->"multiblocks";case SPAWNS->"spawn_rules";case POTIONS->"potions";case EFFECTS->"effects";case ENCHANTMENTS->"enchantments";case TRADES->"trades";case BREWING->"brewing";case WORKSTATIONS->"workstation_rules";default->"loot_entrypoints";};var declaration=new com.fasterxml.jackson.databind.ObjectMapper().readTree(profile.descriptor()).path("categories").path(capability);if(!Set.of("COMPLETE","COMPLETE_WITH_ERRORS").contains(declaration.path("status").asText())){Platform.runLater(()->{if(token==request){list.getItems().clear();status.setText("该快照没有可用的此类规则能力；需重新导出，不能据此判断没有相关内容。");}});return;}}var page=catalog.page(profile.id(),kind,query,ns,start,50);Platform.runLater(()->{if(token!=request)return;total=page.total();list.getItems().setAll(page.entries());status.setText(total+" 条 · "+(total==0?0:start+1)+"–"+Math.min(start+50,total));});}catch(Exception e){Platform.runLater(()->{if(token==request)status.setText("读取失败："+e.getMessage());});}});}
    private void show(RuntimeCatalog.Entry entry){long token=++selection;image.setImage(null);render.setDisable(true);var profile=profiles.getValue();if(entry==null||profile==null){json.clear();return;}origin.setText(profile.environment()+"\n快照："+profile.id()+"\n来源："+profile.source()+"\n类别："+entry.category()+" · "+entry.key());worker.execute(()->{if(token!=selection)return;try{String text=(RuntimeRules.CATEGORIES.contains(entry.category())?RuntimeRules.describe(entry.category(),new com.fasterxml.jackson.databind.ObjectMapper().readTree(entry.json()))+"\n原始JSON：\n":"")+catalog.pretty(entry);byte[] bytes=null;var row=new com.fasterxml.jackson.databind.ObjectMapper().readTree(entry.json());
            if(RuntimeStructures.CATEGORIES.contains(entry.category()))text=RuntimeStructures.describe(entry.category(),row)+"\n原始JSON：\n"+text;
            if(entry.category().equals("spawn_rules"))text=RuntimeSpawns.describe(row)+"\n原始记录：\n"+text;
            if(RuntimeMagic.CATEGORIES.contains(entry.category()))text=RuntimeMagic.describe(entry.category(),row)+"\n原始记录：\n"+text;
            if(kind==RuntimeCatalog.Kind.ENTITIES||kind==RuntimeCatalog.Kind.ITEMS)text=RuntimeAttributes.details(db,profile.id(),row.path("id").asText(),row.path("stateKey").asText("default"))+"\n原始记录：\n"+text;
            if(kind==RuntimeCatalog.Kind.ITEMS){text=catalog.itemRelations(profile.id(),row.path("id").asText())+"\n原始记录：\n"+text;var icon=new ItemIconService(db,config.getDataDir()).snapshot();if(profile.id().equals(RuntimeKnowledgeStore.active(db))){var item=icon.item(row.path("id").asText(),false,null);if(item.image()!=null){var out=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(item.image(),"png",out);bytes=out.toByteArray();}}}
            if(kind==RuntimeCatalog.Kind.SPAWNS&&!row.has("error")){var resolved=catalog.defaultEntityImage(profile.id(),row.path("id").asText());if(resolved.has("assetPath"))bytes=catalog.entityBytes(resolved,config.getDataDir());}
            if(kind==RuntimeCatalog.Kind.ENTITIES&&entry.category().equals("entity_icons")){var resolved=catalog.entityImage(profile.id(),entry);if(resolved.has("assetPath"))bytes=catalog.entityBytes(resolved,config.getDataDir());}
            if(profile.id().equals(RuntimeKnowledgeStore.active(db))){
                if(kind==RuntimeCatalog.Kind.RECIPES){var cached=new RendererService(config,db).cachedDetailed(List.of(catalog.recipe(profile.id(),entry.key())));var cardPath=!cached.cards().isEmpty()?cached.cards().getFirst().path():cached.images().values().stream().findFirst().orElse(null);if(cardPath!=null)bytes=Files.readAllBytes(Path.of(cardPath));}
                if(RuntimeRules.CATEGORIES.contains(entry.category())){var cached=new RuleCardService(db,config.getDataDir()).render(profile.id(),entry.category(),entry.key(),true);if(cached!=null)bytes=Files.readAllBytes(cached);}
                if(RuntimeStructures.renderable(entry.category(),row)){Integer layer=row.path("size").path(1).asInt()>8?0:null;var cached=new LayoutCardService(db,config.getDataDir()).render(profile.id(),entry.category(),entry.key(),true,layer);if(cached!=null)bytes=Files.readAllBytes(cached);}
                if(kind==RuntimeCatalog.Kind.LOOT){var cached=new LootCardService(db,config.getDataDir()).cached(profile.id(),entry.category(),entry.key());if(cached!=null)bytes=Files.readAllBytes(cached);}
            }
            String content=text;byte[] png=bytes;Platform.runLater(()->{if(token!=selection)return;json.setText(content.length()>300000?content.substring(0,300000)+"\n…预览已截断，请导出完整JSON查看。":content);if(png!=null)image.setImage(preview(png));if(RuntimeStructures.CATEGORIES.contains(entry.category())&&row.path("size").isArray()){boolean small=row.path("size").path(1).asInt()<=8;allLayers.setSelected(small);int y=entry.category().equals("multiblocks")?-row.path("origin").path(1).asInt():0;layoutLayer.getValueFactory().setValue(small?0:y);}render.setDisable((RuntimeStructures.CATEGORIES.contains(entry.category())&&!RuntimeStructures.renderable(entry.category(),row))||!renderable()||(kind==RuntimeCatalog.Kind.WORKSTATIONS&&!row.path("station").asText().equals("minecraft:anvil")));});
        }catch(Exception e){Platform.runLater(()->{if(token==selection)json.setText("条目读取失败："+e.getMessage());});}});}
    private void related(){
        var entry=list.getSelectionModel().getSelectedItem();var profile=profiles.getValue();if(entry==null||profile==null)return;
        worker.execute(()->{try{var values=catalog.related(profile.id(),entry);Platform.runLater(()->{
            var dialog=new Dialog<Void>();dialog.setTitle("关联规则与定义");dialog.setResizable(true);dialog.getDialogPane().getButtonTypes().add(ButtonType.CLOSE);dialog.getDialogPane().setPrefSize(1100,780);if(getScene()!=null)dialog.initOwner(getScene().getWindow());
            var choices=new ListView<RuntimeCatalog.Entry>();choices.getItems().setAll(values);var details=new TextArea();details.setEditable(false);var picture=new ImageView();picture.setPreserveRatio(true);picture.setFitWidth(640);picture.setFitHeight(0);picture.setSmooth(false);var draw=new Button("渲染选中的规则");var message=new Label(values.isEmpty()?"没有已解析的关联；动态规则或旧包可能存在覆盖缺口。":"选择来源查看原始规则与图片");draw.setDisable(true);final long[] sequence={0};
            choices.getSelectionModel().selectedItemProperty().addListener((o,a,b)->{sequence[0]++;picture.setImage(null);draw.setDisable(b==null||!(RuntimeRules.CATEGORIES.contains(b.category())||Set.of("loot_tables","loot_modifiers","recipes").contains(b.category())||Set.of("multiblocks","structure_templates").contains(b.category())));try{details.setText(b==null?"":catalog.pretty(b));}catch(Exception failure){details.setText(failure.getMessage());}});
            draw.setOnAction(event->{var selected=choices.getSelectionModel().getSelectedItem();if(selected==null)return;long token=sequence[0];draw.setDisable(true);worker.execute(()->{try{Path file;if(Set.of("multiblocks","structure_templates").contains(selected.category()))file=new LayoutCardService(db,config.getDataDir()).render(profile.id(),selected.category(),selected.key(),false,null);else if(RuntimeRules.CATEGORIES.contains(selected.category()))file=new RuleCardService(db,config.getDataDir()).render(profile.id(),selected.category(),selected.key(),false);else if(Set.of("loot_tables","loot_modifiers").contains(selected.category()))file=new LootCardService(db,config.getDataDir()).render(profile.id(),selected.category(),selected.key());else if(selected.category().equals("recipes")){var cards=new RendererService(config,db).renderDetailed(List.of(catalog.recipe(profile.id(),selected.key())));if(cards.cards().isEmpty()&&cards.images().isEmpty())throw new IllegalArgumentException("此配方没有可渲染结果");file=Path.of(cards.cards().isEmpty()?cards.images().values().iterator().next():cards.cards().getFirst().path());}else throw new IllegalArgumentException("此关联为入口声明，请在JSON中继续定位掉落表");byte[] bytes=Files.readAllBytes(file);Platform.runLater(()->{draw.setDisable(false);if(token==sequence[0])picture.setImage(new Image(new java.io.ByteArrayInputStream(bytes)));});}catch(Exception failure){Platform.runLater(()->{draw.setDisable(false);if(token==sequence[0])message.setText(failure.getMessage());});}});});
            var pictureScroll=new ScrollPane(picture);pictureScroll.setPrefHeight(360);pictureScroll.viewportBoundsProperty().addListener((o,a,b)->{if(b.getWidth()>0)picture.setFitWidth(Math.max(160,b.getWidth()-20));});var preview=new VBox(8,message,draw,pictureScroll,details);VBox.setVgrow(details,Priority.ALWAYS);dialog.getDialogPane().setContent(new SplitPane(choices,preview));dialog.show();
        });}catch(Exception failure){Platform.runLater(()->status.setText("关联读取失败："+failure.getMessage()));}});
    }
    private boolean renderable(){return kind==RuntimeCatalog.Kind.TEMPLATES||kind==RuntimeCatalog.Kind.MULTIBLOCKS||kind==RuntimeCatalog.Kind.RECIPES||kind==RuntimeCatalog.Kind.LOOT||kind==RuntimeCatalog.Kind.TRADES||kind==RuntimeCatalog.Kind.BREWING||kind==RuntimeCatalog.Kind.WORKSTATIONS;}
    private void render(){var entry=list.getSelectionModel().getSelectedItem();var profile=profiles.getValue();if(entry==null||profile==null)return;long token=selection;Integer selectedLayer=allLayers.isSelected()?null:layoutLayer.getValue();render.setDisable(true);status.setText("生成或读取本地缓存…");worker.execute(()->{try{if(!profile.id().equals(RuntimeKnowledgeStore.active(db)))throw new IllegalArgumentException("请先在问答页选择该快照的图标环境，再渲染");Path file;
            if(kind==RuntimeCatalog.Kind.RECIPES){var batch=new RendererService(config,db).renderDetailed(List.of(catalog.recipe(profile.id(),entry.key())));if(batch.cards().isEmpty()&&batch.images().isEmpty())throw new IllegalArgumentException(String.join("；",batch.diagnostics()));file=Path.of(batch.cards().isEmpty()?batch.images().values().iterator().next():batch.cards().getFirst().path());}
            else if(RuntimeStructures.CATEGORIES.contains(entry.category()))file=new LayoutCardService(db,config.getDataDir()).render(profile.id(),entry.category(),entry.key(),false,selectedLayer);
            else if(RuntimeRules.CATEGORIES.contains(entry.category()))file=new RuleCardService(db,config.getDataDir()).render(profile.id(),entry.category(),entry.key(),false);
            else file=new LootCardService(db,config.getDataDir()).render(profile.id(),entry.category(),entry.key());byte[] bytes=Files.readAllBytes(file);Platform.runLater(()->{if(token!=selection)return;image.setImage(new Image(new java.io.ByteArrayInputStream(bytes)));render.setDisable(false);status.setText("已就绪，可由后续问答复用："+file.getFileName());});
        }catch(Exception e){Platform.runLater(()->{if(token!=selection)return;render.setDisable(false);status.setText("无法渲染："+e.getMessage());});}});}
}
